import React, { useState } from "react";
import Header from "./components/Header";
import Footer from "./components/Footer";
import Items from "./components/Items";

function App() {
  // Называем переменную items, а не props
  const [items] = useState([
    {
      id: 1,
      title: 'Стул серый',
      img: 'chair-grey.jpg',
      desc: 'Комфортный стул для офиса.',
      category: 'chairs',
      price: '49.99'
    },
    {
      id: 2,
      title: 'Стол',
      img: 'table.jpg',
      desc: 'Минималистичный рабочий стол.',
      category: 'tables',
      price: '149.00'
    },
    {
      id: 3,
      title: 'Диван',
      img: 'sofa.jpg',
      desc: 'Мягкий диван для гостиной.',
      category: 'sofa',
      price: '549.99'
    }
  ]);

  return (
    <div className="wrapper">
      <Header />
      {/* Передаем наш массив items */}
      <Items items={items} />
      <Footer />
    </div>
  );
}
export default App;
